// @ts-check
// GLOBAL POOL design-token generator (no dependencies).
// Pure functions: tokens.json object in → generated file contents out. `build.mjs` writes them to dist/.

/** @typedef {Record<string, any>} Tokens */

export const PREFIX = 'gp';
const BANNER =
  'GENERATED by @gp/tokens (scripts/build.mjs) from tokens.json — do not edit by hand.\n' +
  ' * Source of truth: Figma file QHF8iRUMFgGMcEn3bD25jl (variables). Regenerate: pnpm --filter @gp/tokens build';

const SANS_FALLBACK =
  'ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif';
const MONO_FALLBACK =
  'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace';

// ───────────────────────────── helpers ─────────────────────────────

/** "bg/base" → "bg-base", "ink.800" → "ink-800" */
export function toName(/** @type {string} */ path) {
  return path.replace(/[/.]/g, '-');
}

/** @param {unknown} value */
export function isPrimitiveRef(value) {
  return typeof value === 'string' && /^[a-z]+\.[a-z0-9-]+$/i.test(value);
}

/**
 * Parse a CSS colour as used in tokens.json (#rgb, #rgba, #rrggbb, #rrggbbaa, rgb(), rgba()).
 * Returns null when the value is not a valid colour.
 * @param {unknown} value
 * @returns {{ r: number, g: number, b: number, a: number } | null}
 */
export function parseColor(value) {
  if (typeof value !== 'string') return null;
  const v = value.trim();
  const hex = /^#([0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i.exec(v);
  if (hex) {
    let h = /** @type {string} */ (hex[1]);
    if (h.length <= 4) h = [...h].map((c) => c + c).join('');
    const n = (/** @type {number} */ i) => parseInt(h.slice(i, i + 2), 16);
    return { r: n(0), g: n(2), b: n(4), a: h.length === 8 ? n(6) / 255 : 1 };
  }
  const fn = /^rgba?\(\s*([^)]+)\)$/i.exec(v);
  if (fn) {
    const parts = /** @type {string} */ (fn[1]).split(/\s*,\s*/);
    if (parts.length !== 3 && parts.length !== 4) return null;
    const [r, g, b] = parts.slice(0, 3).map((p) => (/^\d{1,3}$/.test(p) ? Number(p) : NaN));
    const aRaw = parts[3];
    const a = aRaw === undefined ? 1 : /^(0|1|0?\.\d+|1\.0+)$/.test(aRaw) ? Number(aRaw) : NaN;
    const ok = [r, g, b].every((c) => c !== undefined && Number.isInteger(c) && c >= 0 && c <= 255);
    if (!ok || Number.isNaN(a) || a < 0 || a > 1) return null;
    return {
      r: /** @type {number} */ (r),
      g: /** @type {number} */ (g),
      b: /** @type {number} */ (b),
      a,
    };
  }
  return null;
}

/**
 * Resolve a semantic token value ("ink.800" or a literal colour) to a literal colour.
 * @param {Tokens} tokens
 * @param {string} value
 */
export function resolveColor(tokens, value) {
  if (isPrimitiveRef(value)) {
    const [group, shade] = value.split('.');
    const resolved =
      tokens.primitive?.[/** @type {string} */ (group)]?.[/** @type {string} */ (shade)];
    if (typeof resolved !== 'string') throw new Error(`tokens: unresolvable reference "${value}"`);
    return resolved;
  }
  if (!parseColor(value)) throw new Error(`tokens: "${value}" is not a valid colour`);
  return value;
}

/** Normalise "rgba(245,246,246,0.04)" → "rgba(245, 246, 246, 0.04)" for readable CSS. */
function prettyColor(/** @type {string} */ value) {
  return value.replace(/\s*,\s*/g, ', ');
}

/** 0 → "0px", 16 → "16px" */
const px = (/** @type {number} */ n) => `${n}px`;

/** Figma letter-spacing "-3%" → "-0.03em"; "0" → "0". */
export function letterSpacingToEm(/** @type {string | undefined} */ ls) {
  if (ls === undefined || ls === '0' || ls === '0%') return '0';
  const m = /^(-?\d+(?:\.\d+)?)%$/.exec(ls);
  if (!m) throw new Error(`tokens: unsupported letter-spacing "${ls}"`);
  const em = Number((Number(m[1]) / 100).toFixed(6));
  return `${em}em`;
}

/** Strip keys starting with "_" or "$" (notes/descriptions). */
function entries(/** @type {Record<string, any>} */ obj) {
  return Object.entries(obj).filter(([k]) => !k.startsWith('_') && !k.startsWith('$'));
}

/** px value → rem string for media-query breakpoints (Tailwind sorts breakpoints by value within one unit). */
const rem = (/** @type {number} */ n) => `${Number((n / 16).toFixed(4))}rem`;

// ───────────────────────────── model ─────────────────────────────

/**
 * Build a normalised model used by every output.
 * @param {Tokens} tokens
 */
export function buildModel(tokens) {
  /** @type {{ name: string, value: string }[]} */
  const primitiveColors = [];
  for (const [group, shades] of entries(tokens.primitive)) {
    for (const [shade, value] of entries(shades)) {
      if (!parseColor(value))
        throw new Error(`tokens: primitive ${group}.${shade} = "${value}" is not a colour`);
      primitiveColors.push({ name: `${group}-${shade}`, value });
    }
  }

  /** @type {{ path: string, name: string, ref: string, value: string, isRef: boolean }[]} */
  const semanticColors = entries(tokens.semantic).map(([path, ref]) => ({
    path,
    name: toName(path),
    ref,
    value: resolveColor(tokens, ref),
    isRef: isPrimitiveRef(ref),
  }));

  // Every CSS variable name must be unique across primitives and semantics.
  const seen = new Set();
  for (const { name } of [...primitiveColors, ...semanticColors]) {
    if (seen.has(name)) throw new Error(`tokens: duplicate colour variable name "${name}"`);
    seen.add(name);
  }

  const textStyles = entries(tokens.textStyles).map(([name, s]) => ({
    name,
    size: /** @type {number} */ (s.size),
    lineHeight: /** @type {number} */ (s.lh),
    weight: /** @type {number} */ (s.weight),
    letterSpacing: letterSpacingToEm(s.ls),
    family: s.family === 'mono' ? 'mono' : 'sans',
    uppercase: s.transform === 'uppercase',
    tabular: s.numeric === 'tabular-nums',
  }));

  return {
    primitiveColors,
    semanticColors,
    space: entries(tokens.space).map(([k, v]) => ({ name: k, value: /** @type {number} */ (v) })),
    radius: entries(tokens.radius).map(([k, v]) => ({ name: k, value: /** @type {number} */ (v) })),
    breakpoint: entries(tokens.breakpoint).map(([k, v]) => ({
      name: k,
      value: /** @type {number} */ (v),
    })),
    layout: tokens.layout,
    fontSans: `"${tokens.font.sans} Variable", "${tokens.font.sans}", ${SANS_FALLBACK}`,
    fontMono: `"${tokens.font.mono}", "${String(tokens.font.mono).replace(/\s+/g, '')}", ${MONO_FALLBACK}`,
    textStyles,
    effects: entries(tokens.effects).map(([k, v]) => ({
      name: k,
      value: /** @type {string} */ (v),
    })),
    gradients: entries(tokens.gradients).map(([k, v]) => ({
      name: k,
      value: /** @type {string} */ (v),
    })),
    durations: entries(tokens.motion.duration).map(([k, v]) => ({
      name: k,
      value: /** @type {number} */ (v),
    })),
    eases: entries(tokens.motion.ease).map(([k, v]) => ({
      name: k,
      value: /** @type {string} */ (v),
    })),
  };
}

/** Kebab-case a camelCase layout key: sidebarCollapsed → sidebar-collapsed */
const kebab = (/** @type {string} */ s) => s.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`);

/** Flatten layout tokens: { sidebar: 240, container: { desktop: 1240 } } → [["sidebar",240],["container-desktop",1240]] */
function flattenLayout(/** @type {Record<string, any>} */ layout, prefix = '') {
  /** @type {[string, number][]} */
  const out = [];
  for (const [k, v] of entries(layout)) {
    const key = prefix ? `${prefix}-${kebab(k)}` : kebab(k);
    if (typeof v === 'number') out.push([key, v]);
    else out.push(...flattenLayout(v, key));
  }
  return out;
}

// ───────────────────────────── tokens.css ─────────────────────────────

/** @param {Tokens} tokens */
export function generateTokensCss(tokens) {
  const m = buildModel(tokens);
  const v = (/** @type {string} */ name, /** @type {string | number} */ value) =>
    `  --${PREFIX}-${name}: ${value};`;
  const lines = [
    `/* ${BANNER}\n *\n * CSS custom properties for every primitive and semantic token. Dark is the primary theme. */`,
    ':root {',
    '  color-scheme: dark;',
    '',
    '  /* Primitive colours */',
    ...m.primitiveColors.map((c) => v(c.name, c.value)),
    '',
    '  /* Semantic colours (use these in product code) */',
    ...m.semanticColors.map((c) =>
      v(c.name, c.isRef ? `var(--${PREFIX}-${toName(c.ref)})` : prettyColor(c.ref)),
    ),
    '',
    '  /* Spacing scale (every step = n × 4px) */',
    ...m.space.map((s) => v(`space-${s.name}`, px(s.value))),
    '',
    '  /* Radius */',
    ...m.radius.map((r) => v(`radius-${r.name}`, px(r.value))),
    '',
    '  /* Breakpoints (reference values — custom properties cannot be used inside @media) */',
    ...m.breakpoint.map((b) => v(`breakpoint-${b.name}`, px(b.value))),
    '',
    '  /* Layout */',
    ...flattenLayout(m.layout).map(([k, n]) => v(`layout-${k}`, px(n))),
    '',
    '  /* Font families (apps may override with next/font variables) */',
    v('font-sans', m.fontSans),
    v('font-mono', m.fontMono),
    v('font-numeric', 'tabular-nums'),
    '',
    '  /* Typography (text styles) */',
    ...m.textStyles.flatMap((t) => [
      v(`type-${t.name}-size`, px(t.size)),
      v(`type-${t.name}-line-height`, px(t.lineHeight)),
      v(`type-${t.name}-weight`, t.weight),
      v(`type-${t.name}-letter-spacing`, t.letterSpacing),
    ]),
    '',
    '  /* Shadows & effects */',
    ...m.effects.map((e) => v(`shadow-${e.name}`, e.value)),
    '',
    '  /* Gradients (radial glows are banned as page/hero backgrounds — decision #23) */',
    ...m.gradients.map((g) => v(`gradient-${g.name}`, g.value)),
    '',
    '  /* Motion */',
    ...m.durations.map((d) => v(`duration-${d.name}`, `${d.value}ms`)),
    ...m.eases.map((e) => v(`ease-${e.name}`, e.value)),
    '}',
    '',
  ];
  return lines.join('\n');
}

// ───────────────────────────── theme.css (Tailwind v4) ─────────────────────────────

/**
 * Tailwind colour name for a semantic token. Default: "group-name" (bg-base, surface-default, text-secondary,
 * status-success, balance-available, …). Short aliases are added for the two brand families.
 * @param {string} path semantic path, e.g. "brand/primary-hover"
 * @returns {string[]} names (first = canonical)
 */
export function tailwindColorNames(path) {
  const canonical = toName(path);
  const names = [canonical];
  if (path === 'brand/primary') names.push('brand');
  else if (path.startsWith('brand/primary-'))
    names.push(`brand-${path.slice('brand/primary-'.length)}`);
  if (path === 'accent/gold') names.push('gold');
  else if (path.startsWith('accent/gold-')) names.push(`gold-${path.slice('accent/gold-'.length)}`);
  return names;
}

/** shadcn/ui colour slots mapped onto GLOBAL POOL semantic tokens (so generated shadcn components look right). */
export const SHADCN_ALIASES = /** @type {const} */ ({
  background: 'bg/base',
  foreground: 'text/primary',
  card: 'surface/default',
  'card-foreground': 'text/primary',
  popover: 'surface/overlay',
  'popover-foreground': 'text/primary',
  primary: 'brand/primary',
  'primary-foreground': 'text/on-primary',
  secondary: 'surface/raised',
  'secondary-foreground': 'text/primary',
  muted: 'bg/secondary',
  'muted-foreground': 'text/secondary',
  accent: 'surface/raised',
  'accent-foreground': 'text/primary',
  destructive: 'status/danger',
  'destructive-foreground': 'text/on-danger',
  border: 'border/default',
  input: 'border/default',
  ring: 'border/focus',
});

/** @param {Tokens} tokens */
export function generateThemeCss(tokens) {
  const m = buildModel(tokens);
  const byPath = new Map(m.semanticColors.map((c) => [c.path, c]));
  const t = (/** @type {string} */ name, /** @type {string | number} */ value) =>
    `  --${name}: ${value};`;

  /** @type {string[]} */
  const semanticLines = [];
  for (const c of m.semanticColors) {
    for (const name of tailwindColorNames(c.path))
      semanticLines.push(t(`color-${name}`, prettyColor(c.value)));
  }
  const shadcnLines = Object.entries(SHADCN_ALIASES).map(([slot, path]) => {
    const c = byPath.get(path);
    if (!c) throw new Error(`tokens: shadcn alias ${slot} → unknown semantic token ${path}`);
    return t(`color-${slot}`, prettyColor(c.value));
  });

  const layout = flattenLayout(m.layout);
  const spacingNamed = layout.filter(
    ([k]) => !k.startsWith('container-') && !k.startsWith('gutter-'),
  );
  const containers = layout.filter(([k]) => k.startsWith('container-'));
  const gutters = layout.filter(([k]) => k.startsWith('gutter-'));

  const lines = [
    `/* ${BANNER}`,
    ' *',
    ' * Tailwind CSS v4 theme for GLOBAL POOL. In apps/web/src/app/globals.css:',
    ' *   @import "tailwindcss";',
    ' *   @import "@gp/tokens/tokens.css";',
    ' *   @import "@gp/tokens/theme.css";',
    ' *   @import "@gp/tokens/text-styles.css";',
    ' *',
    ' * Classes: bg-bg-base, bg-surface-default, text-text-secondary, border-border-default, bg-brand',
    ' * text-text-on-primary, text-gold, bg-status-danger-tint, text-balance-available, rounded-lg, p-4,',
    ' * w-sidebar, h-topbar, shadow-elevation-2, text-h1 / text-number-m, ease-standard, bg-gradient-gold-jackpot. */',
    '',
    '@theme {',
    "  /* Tailwind's default palette is removed: only GLOBAL POOL colours exist (no invented colours). */",
    '  --color-*: initial;',
    '',
    '  /* Primitive palettes (prefer semantic names below) */',
    ...m.primitiveColors.map((c) => t(`color-${c.name}`, c.value)),
    '',
    '  /* Semantic colours */',
    ...semanticLines,
    '',
    '  /* shadcn/ui slot aliases (bg-background, text-muted-foreground, ring-ring, …) */',
    ...shadcnLines,
    '',
    '  /* Radius (rounded-none / rounded-full are Tailwind built-ins) */',
    '  --radius-*: initial;',
    ...m.radius
      .filter((r) => r.name !== 'none' && r.name !== 'full')
      .map((r) => t(`radius-${r.name}`, px(r.value))),
    '',
    '  /* Spacing: token scale is n × 4px, so p-4 = 16px, gap-0.5 = 2px, p-1.5 = 6px, m-32 = 128px */',
    t('spacing', '4px'),
    ...spacingNamed.map(([k, n]) => t(`spacing-${k}`, px(n))),
    ...gutters.map(([k, n]) => t(`spacing-${k}`, px(n))),
    '',
    '  /* Containers (max-w-desktop, max-w-laptop, …) */',
    ...containers.map(([k, n]) => t(`container-${k.slice('container-'.length)}`, px(n))),
    '',
    '  /* Breakpoints (rem like Tailwind defaults so variants sort correctly): tablet 768, laptop 1280, desktop 1440 */',
    ...m.breakpoint
      .filter((b) => b.name !== 'mobile')
      .map((b) => t(`breakpoint-${b.name}`, rem(b.value))),
    '',
    '  /* Font families (override --gp-font-* on :root, e.g. with next/font variables) */',
    t('font-sans', `var(--${PREFIX}-font-sans, ${m.fontSans})`),
    t('font-mono', `var(--${PREFIX}-font-mono, ${m.fontMono})`),
    '',
    '  /* Text styles as font-size utilities with line-height / letter-spacing / weight (text-h1, md:text-display-m) */',
    ...m.textStyles.flatMap((s) => [
      t(`text-${s.name}`, px(s.size)),
      t(`text-${s.name}--line-height`, px(s.lineHeight)),
      t(`text-${s.name}--letter-spacing`, s.letterSpacing),
      t(`text-${s.name}--font-weight`, s.weight),
    ]),
    '',
    '  /* Shadows & effects */',
    ...m.effects.map((e) => t(`shadow-${e.name}`, e.value)),
    '',
    '  /* Easing curves (ease-standard, ease-spring-out, …); durations live in tokens.css as --gp-duration-* */',
    ...m.eases.map((e) => t(`ease-${e.name}`, e.value)),
    '}',
    '',
    '/* Gradient utilities (bg-gradient-brand-solid, bg-gradient-gold-jackpot, …) */',
    ...m.gradients.map(
      (g) => `@utility bg-gradient-${g.name} {\n  background-image: ${g.value};\n}`,
    ),
    '',
  ];
  return lines.join('\n');
}

// ───────────────────────────── text-styles.css ─────────────────────────────

/** @param {Tokens} tokens */
export function generateTextStylesCss(tokens) {
  const m = buildModel(tokens);
  const sans = `var(--${PREFIX}-font-sans, ${m.fontSans})`;
  const mono = `var(--${PREFIX}-font-mono, ${m.fontMono})`;
  const blocks = m.textStyles.map((s) => {
    const decl = [
      `font-family: ${s.family === 'mono' ? mono : sans};`,
      `font-size: ${px(s.size)};`,
      `line-height: ${px(s.lineHeight)};`,
      `font-weight: ${s.weight};`,
      `letter-spacing: ${s.letterSpacing};`,
    ];
    if (s.uppercase) decl.push('text-transform: uppercase;');
    if (s.tabular) decl.push('font-variant-numeric: tabular-nums;');
    return `  .text-${s.name} {\n${decl.map((d) => `    ${d}`).join('\n')}\n  }`;
  });
  return [
    `/* ${BANNER}`,
    ' *',
    ' * Text-style classes mirroring the Figma text styles (.text-display-xl … .text-number-s, .text-overline).',
    ' * Plain CSS (works without Tailwind). Placed in the `components` cascade layer so Tailwind utilities',
    ' * (font-bold, md:text-h1, …) can still override them. Number styles use tabular figures. */',
    '',
    '@layer theme, base, components, utilities;',
    '',
    '@layer components {',
    blocks.join('\n\n'),
    '}',
    '',
  ].join('\n');
}

// ───────────────────────────── index.js / index.d.ts ─────────────────────────────

/** @param {Tokens} tokens */
function jsData(tokens) {
  const m = buildModel(tokens);
  return {
    colors: Object.fromEntries(m.semanticColors.map((c) => [c.name, c.value])),
    semanticColorRefs: Object.fromEntries(m.semanticColors.map((c) => [c.name, c.ref])),
    primitiveColors: Object.fromEntries(m.primitiveColors.map((c) => [c.name, c.value])),
  };
}

/** @param {Tokens} tokens @param {'esm' | 'cjs'} format */
export function generateIndexJs(tokens, format) {
  const d = jsData(tokens);
  const body = [
    `const tokens = Object.freeze(${JSON.stringify(tokens, null, 2)});`,
    '',
    '/** Semantic colours resolved to literal values, keyed by CSS variable name without prefix (e.g. "bg-base"). */',
    `const colors = Object.freeze(${JSON.stringify(d.colors, null, 2)});`,
    '',
    '/** The raw reference each semantic colour points to (e.g. "bg-base" → "ink.800"). */',
    `const semanticColorRefs = Object.freeze(${JSON.stringify(d.semanticColorRefs, null, 2)});`,
    '',
    '/** Primitive colours keyed "ink-800", "mint-500", "chain-arbitrum", … */',
    `const primitiveColors = Object.freeze(${JSON.stringify(d.primitiveColors, null, 2)});`,
    '',
    `const TOKEN_PREFIX = ${JSON.stringify(PREFIX)};`,
    '',
    '/** `cssVar("bg-base")` → "var(--gp-bg-base)" */',
    'function cssVar(name) {',
    '  return `var(--${TOKEN_PREFIX}-${name})`;',
    '}',
    '',
  ];
  const names = [
    'tokens',
    'colors',
    'semanticColorRefs',
    'primitiveColors',
    'TOKEN_PREFIX',
    'cssVar',
  ];
  const footer =
    format === 'esm'
      ? `export { ${names.join(', ')} };\nexport default tokens;\n`
      : `module.exports = { ${names.join(', ')}, default: tokens };\n`;
  return `/* ${BANNER} */\n${format === 'cjs' ? "'use strict';\n" : ''}${body.join('\n')}${footer}`;
}

/**
 * Serialise a JSON value as a readonly TypeScript type literal.
 * @param {unknown} value
 * @returns {string}
 */
function typeLiteral(value, indent = '') {
  const next = `${indent}  `;
  if (value === null) return 'null';
  if (Array.isArray(value)) {
    return `readonly [${value.map((/** @type {unknown} */ x) => typeLiteral(x, next)).join(', ')}]`;
  }
  if (typeof value === 'object') {
    /** @type {string[]} */
    const rows = Object.entries(/** @type {Record<string, unknown>} */ (value)).map(
      ([k, v]) => `${next}readonly ${JSON.stringify(k)}: ${typeLiteral(v, next)};`,
    );
    return `{\n${rows.join('\n')}\n${indent}}`;
  }
  return JSON.stringify(value);
}

/** @param {Tokens} tokens */
export function generateIndexDts(tokens) {
  const d = jsData(tokens);
  return [
    `/* ${BANNER} */`,
    `export declare const tokens: ${typeLiteral(tokens)};`,
    '',
    `export declare const colors: ${typeLiteral(d.colors)};`,
    `export declare const semanticColorRefs: ${typeLiteral(d.semanticColorRefs)};`,
    `export declare const primitiveColors: ${typeLiteral(d.primitiveColors)};`,
    `export declare const TOKEN_PREFIX: ${JSON.stringify(PREFIX)};`,
    '',
    'export type Tokens = typeof tokens;',
    'export type SemanticColorName = keyof typeof colors;',
    'export type PrimitiveColorName = keyof typeof primitiveColors;',
    'export type TextStyleName = keyof Tokens["textStyles"];',
    'export type SpaceName = keyof Tokens["space"];',
    'export type RadiusName = keyof Tokens["radius"];',
    '',
    '/** `cssVar("bg-base")` → "var(--gp-bg-base)" */',
    'export declare function cssVar<N extends string>(name: N): `var(--gp-${N})`;',
    '',
    'export default tokens;',
    '',
  ].join('\n');
}

/**
 * Every output file, keyed by its path inside dist/.
 * @param {Tokens} tokens
 */
export function generateAll(tokens) {
  return {
    'tokens.css': generateTokensCss(tokens),
    'theme.css': generateThemeCss(tokens),
    'text-styles.css': generateTextStylesCss(tokens),
    'index.js': generateIndexJs(tokens, 'esm'),
    'index.cjs': generateIndexJs(tokens, 'cjs'),
    'index.d.ts': generateIndexDts(tokens),
    'index.d.cts': generateIndexDts(tokens),
  };
}
